# Check all geometric transformations
def transform_top(r, c, trans):
    # Returns (r, c) after transformation
    match = None
    if trans == 'horz':
        match = (r, 7-c)
    elif trans == 'vert':
        match = (6-r, c)
    elif trans == 'both':
        match = (6-r, 7-c)
    elif trans == 'rot90':
        # 90 deg clockwise: (r, c) -> (c, 6-r)
        match = (c, 6-r)
    elif trans == 'rot270':
        # 270 deg clockwise (90 ccw): (r, c) -> (7-c, r)
        match = (7-c, r)
    return match

# Count matches
trans_matches = {}
for trans in ['horz', 'vert', 'both', 'rot90', 'rot270', 'transposed']:
    matches = 0
    for pos in bottom_9_positions:
        bc, br = pos
        # Try to find a top position that maps here
        for tr, tc in top_9_positions:
            if trans == 'transposed':
                # Transpose: (r, c) -> (c, r)
                target = (tc, tr)
            else:
                target = transform_top(tr, tc, trans)
            if target == pos:
                matches += 1
                break
    trans_matches[trans] = matches

for t, m in trans_matches.items():
    print(f"{t}: {m} matches")

